-- D-14: FSQM-016 Food Safety Plan (HACCP) - Rum Cake, seeded as a DRAFT.
--
-- The rebuilt HACCP plan's controlled home. FSQM-016 was reserved for it in the remediation workbook
-- (2026-09-04, after FSQM-013 went to the Module 11 exemption analysis); nothing in the database or
-- the migrations uses it.
--
-- WHY NOW, INCOMPLETE. Task 14.2's flow diagram exists (Attachment A, C:\AdventureBakes\FSQM-016 Att A
-- ...{drawio,pdf}) and needs a document to be attached to. Tasks 14.1 (team) and 14.4 (significance
-- methodology) are Parts of this document, so they are written into it.
--
-- WHAT IS AND IS NOT WRITTEN. Nine Parts, one per Codex/2.4.3 element. Scope, product description,
-- intended use, the flow diagram, the CCPs as monitored today (FRM-507 / FRM-606) and verification are
-- written from what is on record. Parts 4 (team), 6 (methodology) and 7 (hazard analysis) say NOT YET
-- WRITTEN and name their workbook task - the verify block asserts exactly three such markers, so the
-- plan cannot quietly read as complete. Water activity is stated as not measured (task 14.14).
--
-- THE JUNE 2026 PLAN STAYS IN FORCE until this issues; it is untouched here.
--
-- type fsqm, category 'Food Safety Quality Manual', draft, New.

begin;

do $guard$
begin
  if exists (select 1 from public.sop_documents where sop_number = 'FSQM-016') then
    raise exception 'FSQM-016 already exists.';
  end if;
  if (select count(*) from public.sop_documents where sop_number in ('FRM-507', 'FRM-606', 'FRM-702', 'FRM-007', 'FRM-704', 'FRM-301', 'FRM-701', 'FSQM-017', 'FSQM-018', 'FSQM-009', 'FSQM-015', 'FSQM-039')) <> 12 then
    raise exception 'a document FSQM-016 names does not exist.';
  end if;
  if not exists (select 1 from public.sop_documents where title ilike 'HACCP PLAN%Rum Cake%' and status = 'active') then
    raise exception 'the June 2026 HACCP plan reference document is not where this draft says it is.';
  end if;
end $guard$;

insert into public.sop_documents
  (sop_number, title, type, category, status, revision, sqf_reference, sqf_required, content)
values
  ('FSQM-016', 'Food Safety Plan (HACCP) - Rum Cake', 'fsqm', 'Food Safety Quality Manual', 'draft', 'New',
   '2.4.3.1, 2.4.3.2, 2.4.3.3, 2.4.3.4, 2.4.3.5, 2.4.3.6, 2.4.3.7, 2.4.3.8, 2.4.3.9, 2.4.3.10, 2.4.3.11, 2.4.3.12, 2.4.3.13, 2.4.3.14, 2.4.3.15, 2.4.3.16, 2.3.1.3', true, $q${"purpose": "This is the food safety plan for the rum cake. It states, to the twelve steps of the Codex Alimentarius HACCP guidelines, how Adventure Bakery identifies the hazards in making it, decides which are significant, and controls them, and how that control is monitored, corrected and verified.", "scope": "The rum cake, all flavours, from the receipt of ingredients and packaging to dispatch to the customer's carrier, across the three-day production rotation. Other products made on the site are not covered by this plan.", "definitions": "Critical control point (CCP): a step at which control is applied and is essential to prevent or eliminate a food safety hazard or reduce it to an acceptable level.\nCritical limit: the value that separates safe from unsafe product at a CCP.\nFood safety team: the people named in Part 4 who develop, maintain and review this plan.\nAttachment A: the process flow diagram, held with this plan as an editable master and a PDF.", "responsibility": "SQF Practitioner - leads the food safety team, maintains this plan, and reviews the CCP records.\nFood safety team - develops and reviews this plan, confirms the flow diagram on the floor, and conducts the hazard analysis.\nManagement team - approves this plan and provides what it requires.\nProduction staff - monitor the CCPs and record them on FRM-507 and FRM-606, and stop and hold product when a limit is not met.", "procedure": ["Scope", "> The plan starts at the receipt of ingredients and packaging and ends when finished product is collected by the customer's carrier. Every input and output in between - raw materials, packaging, service inputs, the two overnight delays, waste and rework - is shown on the flow diagram in Attachment A (SQF 2.4.3.3).", "Product description", "• Product: rum cake, in several flavours, made for Bahamas Rum Cake Factory. A shelf-stable baked product, stored and distributed at ambient temperature.", "• Composition: cake mix (containing wheat flour, sugar and nonfat dry milk), liquid whole eggs, soybean oil, water and flavour emulsion; after baking, dipped in a syrup of water, sugar and rum.", "• Allergens: wheat, milk, egg and soy, as declared on each flavour's approved label.", "• Packaging: vacuum-sealed pouch in a baking cup, in an individual product box; boxes packed in coded master cases, palletized and stretch wrapped.", "• Shelf life: 12 months, printed on the pack as a Best By month and year.", "• Water activity and pH: not yet measured.", "> Each flavour's finished product specification is its entry on FRM-704, which this description refers to (SQF 2.4.3.4). The product is called shelf stable because of reduced water activity, but that figure has not been measured, and the syrup added after baking returns water and sugar to the product. The measured water activity of the finished, sealed product is to be recorded here before the hazard analysis in Part 7 is written, because it decides whether pathogen growth in the finished product is a significant hazard.", "Intended use", "• Ready to eat; no further cooking by the consumer.", "• General public. The product contains rum. The June 2026 plan cautioned against its use by immunocompromised individuals, infants and pregnant women without physician guidance; the food safety team is to confirm that caution and the vulnerable groups it names (SQF 2.4.3.5).", "Food safety team", "> NOT YET WRITTEN - workbook task 14.1. The team, its members' disciplines, and how often it meets will be stated here. SQF 2.4.3.2 requires the team to include the SQF Practitioner and people with technical and production knowledge of the product and process, and an auditor will check that at least one member holds a HACCP training certificate.", "Process flow diagram", "• The flow diagram is Attachment A. It shows every step from receipt to dispatch across the three days, every raw material, packaging item and service input, the two scheduled overnight delays, and every output including waste and the one rework loop.", "• The food safety team confirms it on the floor, on each day of the rotation, and records that by dating and signing the confirmation block on the diagram. That signed block is the confirmation SQF 2.4.3.6 requires.", "• The diagram is re-confirmed whenever the process, equipment or rotation changes, and at the annual review of this plan.", "> FSQM-039 Facility Layout and Product Flow shows where equipment stands and where product goes on the floor. It is not this flow diagram and is not offered as one.", "Hazard significance methodology", "> NOT YET WRITTEN - workbook task 14.4. How the likelihood and severity of a hazard decide whether it is significant, written before the hazard analysis and applied the same way to every step (SQF 2.4.3.8).", "Hazard analysis and control measures", "> NOT YET WRITTEN - workbook tasks 14.5 and 14.6. Every biological, chemical and physical hazard reasonably expected at each step on Attachment A, its significance under Part 6, and the control measure for each significant hazard (SQF 2.4.3.7 to 2.4.3.9). Until this Part is written, the hazard analysis in the June 2026 plan remains the one in force.", "Critical control points", "• CCP 1 - Baking: oven at least 350°F for at least 27 minutes, recorded on FRM-507 CCP 1 Baking Monitoring Record. The June 2026 plan also sets an internal temperature of at least 180°F at the end of the bake; the product is not probed today, and FRM-507 records that.", "• CCP 2 - Vacuum sealing: every pouch sealed intact with no leak, channel, wrinkle or partial seal, checked with the pull test, recorded on FRM-606 CCP 2 Vacuum Sealing Monitoring Record. The vacuum level and seal width for the site's machine are not yet confirmed.", "• A failed limit stops the step. The affected product is held on FRM-702 and dispositioned under FSQM-018, and the cause is corrected under FSQM-009 on FRM-007 (SQF 2.4.3.13).", "> The CCPs are carried forward from the June 2026 plan so that they are monitored and recorded while this plan is rebuilt. They are re-determined from the hazard analysis in Part 7 and their critical limits validated under workbook tasks 14.7 to 14.9 (SQF 2.4.3.10 and 2.4.3.11); this Part is revised then.", "Verification and review", "• The CCP records are reviewed and signed weekly under FSQM-017 (SQF 2.4.3.15 and 2.4.3.16).", "• The food safety team reviews this plan in full at least annually, and whenever the product, ingredients, process, equipment or packaging changes in a way that could affect food safety (SQF 2.4.3.14 and 2.3.1.3)."], "form_references": "FRM-507 - CCP 1 Baking Monitoring Record\nFRM-606 - CCP 2 Vacuum Sealing Monitoring Record\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-007 - Corrective and Preventive Action record (FSQM-009)\nFRM-704 - Finished Product Specification\nFRM-301 - Incoming Material Receiving & Inspection Log\nFRM-701 - Finished Product Release Record", "records": "• Attachment A, with its confirmation block dated and signed\n• FRM-507 and FRM-606 CCP monitoring records, with their weekly review signatures\n• FRM-702 holds and FRM-007 corrective actions arising from a CCP deviation\n• Food safety team meeting records, once Part 4 is written\nSuperseded revisions of this plan are retained by the sop_document_history trigger.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 2.4.3 Food Safety Plan, and 2.3.1.3. Codex Alimentarius, General Principles of Food Hygiene (CXC 1-1969), HACCP system and guidelines for its application.\n\nTHIS PLAN REPLACES THE HACCP PLAN OF 23 JUNE 2026, version 1.0, held as an unnumbered reference document with an unsigned approval page. That plan stays in force until this one is issued, and is then archived, not deleted.\n\nFSQM-017 Validation and Verification Program - the verification schedule the CCP record reviews sit on.\nFSQM-039 Facility Layout and Product Flow - the floor layout and hygiene zoning; not the flow diagram.\nFSQM-015 Environmental Monitoring Program - depends on the water activity this plan records.\nFSQM-018 Non-Conforming Product and Equipment, and FSQM-009 Corrective and Preventive Action Program - deviation handling.\n\nThe product is subject to 21 CFR 117 (Preventive Controls for Human Food). Whether the site is exempt, and on what basis, is decided under workbook task 14.12 and recorded here.", "revision_history": "New - 2026-09-21 - DRAFT, under D-14. Created so the rebuilt plan has a controlled home while it is written, and so the flow diagram (task 14.2) can be attached to it as Attachment A.\n\nWHAT IS WRITTEN: scope, product description, intended use, the flow diagram Part, the CCPs as they are monitored today, and verification.\n\nWHAT IS NOT: Parts 4, 6 and 7 are marked NOT YET WRITTEN and name the workbook task that writes each. A plan that read as complete before its hazard analysis existed would be the defect the gap assessment found, repeated.\n\nThe number FSQM-016 was reserved for this plan in the remediation workbook on 2026-09-04, after FSQM-013 went to the Module 11 exemption analysis."}$q$::jsonb);

do $verify$
declare r record; p jsonb;
begin
  select status, revision, type, content into r from public.sop_documents where sop_number = 'FSQM-016';
  p := r.content->'procedure';
  if (r.status, r.revision, r.type) is distinct from ('draft', 'New', 'fsqm') then
    raise exception 'FSQM-016 wrong: %/%/%.', r.status, r.revision, r.type;
  end if;
  if jsonb_array_length(p) <> 32 then raise exception 'procedure is % lines, expected 32.', jsonb_array_length(p); end if;
  if (select count(*) from jsonb_array_elements_text(p) l where l like '%NOT YET WRITTEN%') <> 3 then
    raise exception 'expected exactly 3 NOT YET WRITTEN Parts.';
  end if;
  if p::text not like '%Attachment A%' or p::text not like '%Water activity and pH: not yet measured%' then
    raise exception 'flow diagram Part or water activity statement missing.';
  end if;
  raise notice 'FSQM-016 seeded as a draft: % procedure lines, 3 Parts not yet written.', jsonb_array_length(p);
end $verify$;

commit;
